package com.example.examplemod.city;
import com.example.examplemod.client.screen.CommunityLayout;
import com.example.examplemod.alliance.AllianceBook;
import com.example.examplemod.network.CommunityRequestPayload;
import net.minecraft.core.BlockPos;
import net.minecraft.core.RegistryAccess;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import java.util.*;
public final class CityMembershipCheck {
    private static int checks;private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    public static void main(String[] args){
        UUID owner=UUID.randomUUID(),admin=UUID.randomUUID(),resident=UUID.randomUUID(),outsider=UUID.randomUUID();var manager=new CityManager();var city=manager.createCity("Membership test",owner,BlockPos.ZERO);require(city!=null,"city created");city.addMember(admin,CityMember.Role.ADMIN);city.addMember(resident,CityMember.Role.RESIDENT);
        require(CityMembershipService.mayKick(city,owner,admin),"owner can remove admin");require(!CityMembershipService.mayKick(city,admin,owner),"admin cannot remove owner");require(!CityMembershipService.mayKick(city,admin,admin),"admin cannot remove self");require(!CityMembershipService.mayKick(city,owner,owner),"owner cannot remove self");require(!CityMembershipService.mayKick(city,owner,outsider),"outsider target denied");require(!CityMembershipService.mayKick(city,outsider,resident),"outsider actor denied");require(!CityMembershipService.mayKick(city,null,resident)&&!CityMembershipService.mayKick(city,owner,null),"missing UUID denied");
        for(var role:CityMember.Role.values())if(role!=CityMember.Role.OWNER){city.setMemberRole(resident,role);require(CityMembershipService.mayKick(city,owner,resident),"owner may remove "+role);require(CityMembershipService.mayKick(city,admin,resident)==(role!=CityMember.Role.ADMIN),"admin hierarchy "+role);if(role!=CityMember.Role.ADMIN)require(!CityMembershipService.mayKick(city,resident,admin),"nonadmin cannot remove admin");}
        city.setMemberRole(resident,CityMember.Role.BUILDER);require(manager.allowsTerritoryAction(city,resident,true),"builder has city land access");city.removeMember(resident);require(manager.getMemberCity(resident)==null&&!manager.allowsTerritoryAction(city,resident,true),"removal revokes city and land access");city.removeMember(resident);require(city.getMemberCount()==2,"duplicate removal harmless");city.removeMember(owner);require(city.hasMember(owner),"model protects owner");
        require(!city.transferOwnership(admin,owner)&&!city.transferOwnership(owner,outsider),"only owner to a current member");require(!city.transferOwnership(owner,owner),"self transfer refused");require(CityMembershipService.mayTransfer(city,owner,admin)&&!CityMembershipService.mayTransfer(city,admin,owner),"transfer policy");require(city.transferOwnership(owner,admin),"ownership transferred");require(city.getOwner().equals(admin)&&city.getMember(admin).getRole()==CityMember.Role.OWNER&&city.getMember(owner).getRole()==CityMember.Role.ADMIN,"owner UUID and roles consistent");require(city.getMembers().stream().filter(m->m.getRole()==CityMember.Role.OWNER).count()==1,"exactly one owner");
        var loaded=CityManager.load(manager.save(new CompoundTag(),null),null);var restored=loaded.getCity(city.getId());require(restored.getOwner().equals(admin)&&restored.isOwner(admin)&&restored.getMember(owner).getRole()==CityMember.Role.ADMIN,"existing city format persists ownership transfer");require(loaded.getCityByOwner(owner)==null&&loaded.getCityByOwner(admin)==restored,"owner lookup follows transfer");restored.removeMember(owner);require(loaded.getMemberCity(owner)==null,"previous owner can now leave");
        var events=new CityMembershipEvents();var receipt=new CityMembershipEvents.Receipt(owner,UUID.randomUUID(),city.getId(),resident,"KICK");events.record(receipt);events.notices.put(resident,new CityMembershipEvents.Notice("kicked",city.getName()));var reloaded=CityMembershipEvents.load(events.save(new CompoundTag(),null),null);require(reloaded.done(receipt),"request replay survives restart");require(reloaded.notices.get(resident).city().equals(city.getName()),"offline notice survives restart");require(!reloaded.done(new CityMembershipEvents.Receipt(outsider,receipt.request(),receipt.city(),receipt.target(),receipt.action())),"receipt cannot be reused by another actor");for(int i=0;i<1030;i++)events.record(new CityMembershipEvents.Receipt(owner,UUID.randomUUID(),city.getId(),resident,"KICK"));require(events.receipts.size()==1024,"receipt bound");
        var book=new AllianceBook();var founder=new AllianceBook.CityRef(city.getId(),city.getName(),admin,Set.of(owner,admin));book.apply(new AllianceBook.Command(UUID.randomUUID(),AllianceBook.Action.CREATE,null,null,0,"City union","",0xD3A363,0),admin,founder,Map.of(founder.id(),founder),"Owner",1);var alliance=book.city(founder.id());alliance.representatives.put(founder.id(),owner);var departed=new AllianceBook.CityRef(founder.id(),founder.name(),admin,Set.of(admin));require(book.representative(alliance,departed).equals(admin),"departed council representative falls back to owner");
        var buf=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.EMPTY);try{for(var action:List.of(CommunityRequestPayload.Action.LEAVE,CommunityRequestPayload.Action.KICK,CommunityRequestPayload.Action.TRANSFER)){buf.clear();var p=new CommunityRequestPayload(UUID.randomUUID(),action,city.getId(),resident,null,0,0,"");CommunityRequestPayload.STREAM_CODEC.encode(buf,p);require(CommunityRequestPayload.STREAM_CODEC.decode(buf).equals(p),"membership action codec "+action);}}finally{buf.release();}
        for(int[] size:new int[][]{{320,180},{426,240},{640,360},{1920,1080}}){var layout=CommunityLayout.calculate(size[0],size[1]);var modal=layout.membershipModal();for(boolean accept:List.of(false,true)){var button=layout.membershipConfirm(accept);require(modal.contains(button.x(),button.y())&&modal.contains(button.right()-1,button.bottom()-1),"modal button stays inside panel");var screen=layout.screen(button,0);require(button.contains(layout.localX(screen.x()+screen.width()/2d),layout.localY(screen.y()+screen.height()/2d)),"confirmation paint/hit geometry agrees");}}
        System.out.println("PASS: "+checks+" city leave/kick/transfer permissions, persistence, replay, alliance and GUI assertions");
    }
}
